@charset "UTF-8";

:root {
  --main-color: #333;
  --right-color: #c8e2f7;
  --dark-color: #166fb7;
}

/* ----------------------------------------
  reset
---------------------------------------- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
ul {
  list-style: none;
}
a {
  color: inherit;
  text-decoration: none;
}
img {
  max-width: 100%;
  vertical-align: bottom;
}
html {
  font-size: 100%;
}


/* ----------------------------------------
  body
---------------------------------------- */
body {
  background-color: #fff;
  color: var(--main-color);
  font-size: 1.0rem;
  font-family: "Poppins", "Noto Sans JP", sans-serif;
  line-height: 1.0;
}


/* ------------------------------------------
  layout
------------------------------------------ */
.container {
  width: min(88%, 1000px);
  margin: 0 auto;
}


/* ------------------------------------------
  header
------------------------------------------ */
.header {
  padding: 20px 0;
  background-color: var(--right-color);

  h1 {
    font-size: 1.25rem;
  }

}



/* ------------------------------------------
  main
------------------------------------------ */

/* ---------------- .hero ---------------- */
.hero {
  background-color: var(--right-color);
  text-align: center;

  .container {
    display: grid;
    place-content: center;
    place-items: center;
    position: relative;
    padding-block: 200px 100px;
  }

  img {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translateX(-50%) translateY(-50%);
    height: 130%;
  }

  h2 {
    font-size: 1.375rem;
    line-height: 1.2;
    white-space: initial;
    z-index: 100;

    span {
      font-size: 6.35rem;
    }

  }

  p {
    max-width: 510px;
    margin: 0 auto 30px;
    font-size: 1.0rem;
    text-align: left;
    line-height: 1.7;
    z-index: 100;
  }

  a {
    display: inline-block;
    padding: 20px 80px;
    background-color: var(--dark-color);
    border-radius: 100px;
    color: #fff;
    font-weight: 700;
    z-index: 100;
  }

}

@media screen and (max-width: 767px) {
  .hero {

    .container {
      display: grid;
      place-content: center;
      place-items: center;
      position: relative;
      padding: 60px 0 30px;
    }

    img {
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translateX(-50%) translateY(-80%);
      height: 80%;
    }

    h2 {
      margin-bottom: 20px;
      font-size: 1.0rem;
      white-space: pre-line;

      span {
        font-size: 2.45rem;
        line-height: 1.2;
        white-space: initial;
        z-index: 100;
      }
    }

    p {
      max-width: 510px;
      padding: 0 20px;
      font-size: 0.87rem;
      text-align: left;
      line-height: 1.6;
      text-align: justify;
      z-index: 100;
    }

    a {
      width: 90%;
      padding: 0 80px;
      background-color: var(--dark-color);
      border-radius: 0;
    }

  }

}


/* ---------------- .about ---------------- */
.about {
  padding: 70px 0;

  .container {
    display: grid;
    grid-template-columns: 56% 34%;
    gap: 10%;
  }

    .text_block {
      display: grid;
      place-content: center;
    }

    h3 {
      color: var(--main-color);
      font-size: 2.375rem;
      line-height: 1.2;
      white-space: pre-line;
    }

    span {
      display: block;
      padding: 20px 0;
      color: var(--dark-color);
      font-size: 1.75rem;
    }

    p {
      line-height: 1.7;
      white-space: pre-line;
    }

}

@media screen and (max-width: 767px) {
  .about {
    padding: 40px 0 30px;

    .container {
      display: block;
    }

    h3 {
      margin-bottom: 20px;
      font-size: 1.415rem;
      line-height: 1.1;
    }

    span {
      padding: 10px 0 6px;
      color: var(--dark-color);
      font-size: 1.425rem;
    }

    p {
      margin-bottom: 20px;
      font-size: 0.875rem;
      line-height: 1.5;
      text-align: justify;
    }

    img {
      width: 100%;
      height: 200px;
      object-fit: cover;
    }

  }
}


/* --------------- .service --------------- */
.service {
  padding: 70px 0;
  background-color: var(--right-color);
  text-align: center;

  h3 {
    color: var(--main-color);
    font-size: 2.2rem;
    line-height: 1.3;
    white-space: pre-line;
  }

  span {
    display: block;
    padding: 20px 0;
    color: var(--dark-color);
    font-size: 1.75rem;
  }

}

  .service_type {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 3%;
    margin: 10px 0;

    li {
      padding: 24px;
      background-color: #fff;
      box-shadow: 0 3px 20px 0 rgba(0, 0, 0, 0.2);
    }

    h4 {
      color: var(--dark-color);
      font-size: 1.25rem;
    }

    img {
      height: 167px;
      object-fit: cover;
      margin: 16px 0;
    }

    p {
      font-size: 0.875rem;
      text-align: left;
      line-height: 1.7;
      text-align: justify;
      white-space: pre-line;
    }

  }

@media screen and (max-width: 767px) {
  .service {
    padding: 40px 0 10px;

    h3 {
      margin-bottom: 0;
      font-size: 1.375rem;
      line-height: 1.1;
    }

    span {
      display: block;
      padding: 6px 0 20px;
      color: var(--dark-color);
      font-size: 1.425rem;
    }

  }

  .service_type {
    display: block;
    margin-bottom: 0;

    li {
      margin-bottom: 20px;
      padding: 24px;
    }

  }
}


/* --------------- .company --------------- */
.company {
  padding: 70px 0;

  .container {
    display: grid;
    grid-template-columns: 40% 50%;
    gap: 6%;
  }

    .text_block {
      display: grid;
      place-content: center;
    }

    h3 {
      color: var(--main-color);
      font-size: 2.375rem;
      line-height: 1.3;
      white-space: pre-line;
    }

    span {
      display: block;
      padding: 20px 0 ;
      color: var(--dark-color);
      font-size: 1.75rem;
    }

    p {
      line-height: 1.7;
      text-align: justify;
      white-space: pre-line;
    }

    img {
      height: 400px;
      width: 100%;
      object-fit: cover;
      border-radius: 50%;
    }

}

@media screen and (max-width: 767px) {
  .company {
    padding: 30px 0 20px;

    .container {
      display: block;
    }

    img {
      height: 260px;
      width: 100%;
      object-fit: cover;
      border-radius: 0;
      margin-bottom: 20px;
    }

    h3 {
      font-size: 1.475rem;
      line-height: 1.3;
    }

    span {
      padding-bottom: 20px;
      font-size: 1.275rem;
    }

  }
}


/* --------------- .contact --------------- */
.contact {
  padding: 70px 0;
  background-color: var(--right-color);
  text-align: center;

  img {
    width: 1000px;
    height: 260px;
    object-fit: cover;
  }

  h3 {
    margin: 30px 0;
    color: var(--main-color);
    font-size: 2.375rem;
    line-height: 1.3;
  }

  p {
    max-width: 510px;
    margin: 0 auto 30px;
    font-size: 0.875rem;
    text-align: left;
    line-height: 1.7;
    white-space: pre-line;
    text-align: justify;
    z-index: 100;
  }

  a {
    display: inline-block;
    padding: 20px 80px;
    background-color: var(--dark-color);
    border-radius: 100px;
    color: #fff;
    font-weight: 700;
    z-index: 100;
  }
}

@media screen and (max-width: 767px) {
  .contact {
    padding: 40px 0 30px;

    h3 {
      margin: 30px 0 10px;
      font-size: 1.475rem;
    }

    p {
      margin: 0 auto 20px;
      padding: 0 1.0rem;
      font-size: 0.875rem;
      text-align: left;
      line-height: 1.7;
      white-space: pre-line;
      z-index: 100;
    }

    a {
      width: 92%;
      border-radius: 0;
    }

  }

}


/* ------------------------------------------
  footer
------------------------------------------ */
.footer {
  padding: 30px 0;
  background-color: var(--dark-color);

  p {
    color: #fff;
    font-size: 0.875rem;
    text-align: center;
  }

}

@media screen and (max-width: 767px) {
  .footer {
    padding: 20px 0;
