script.js
$(function () {

/* =================================================
  Call To Actionを、一定時間後に発動させる設定   
================================================= */ 
  // id名「cta」の値を取得
  const cta = $('#cta');

  // ctaを、最初は非表示にしておく
  cta.hide();

  function call() {
    cta.fadeIn();
  }
  // 一定時間後に発動させる内容を関数にしておく

  setTimeout(call, 2000);
  // setTimeoutで、2秒後に関数callを呼び出している

  const pr_close = $('#cta .close');
  pr_close.on('click', function () {
      cta.fadeOut();
  });
  // 閉じるボタンを押すと、ctaがフェードアウトする

  cta.on('click', function () {
      $(this).fadeOut();
  });
  // cta自身をクリックすると自身がフェードアウトする


  const pr = $('#cta .pr');
  pr.on('click', function (e) {

      e.stopPropagation();  // クリックイベントの伝播を防ぐ

      })
  // 厳密には、pr上のどこを押しても親要素に場所までイベントが伝播してしまうので
  // その伝播を防ぐ必要がある

});

